import json, statistics
def load(name):
    return [json.loads(l) for l in open(f'adapters/{name}/practice_rows.jsonl')]
def close(d): return round(d,3)
for name, target in [('r1','red_cube'),('v1','green_cube')]:
    rows=load(name)
    d_end=[]; d_any=[]; lifts=[]; near=0; near_lift=0; n=0
    for r in rows:
        fs=r.get('final_state') or {}
        if not fs or r.get('sandbox_rc')!=0: continue
        g=(fs.get('grippers') or {}).get('arm0') or {}
        ob=(fs.get('objects') or {}).get(target) or {}
        gp=g.get('pos'); cp=ob.get('pos'); ip=ob.get('init_pos'); mz=ob.get('max_z')
        if not gp or not cp: continue
        n+=1
        dist=(gp[0]-cp[0])**2+(gp[1]-cp[1])**2+(gp[2]-cp[2])**2
        d_end.append(dist**0.5)
        if ip and mz is not None:
            lifts.append(mz-ip[2])
        if dist**0.5<0.06: near+=1
        if dist**0.5<0.06 and ip and mz is not None and mz-ip[2]>0.1: near_lift+=1
    print('='*60); print(name, target, 'rc0 n=',n)
    def mm(a): 
        a=sorted(a); 
        return dict(n=len(a),min=close(a[0]),p25=close(a[len(a)//4]),med=close(a[len(a)//2]),p75=close(a[3*len(a)//4]),max=close(a[-1]),mean=close(sum(a)/len(a))) if a else None
    print('gripper-target end distance m:', mm(d_end))
    print('target lifted m (max_z - init_z):', mm(lifts))
    print('ended within 6cm of cube:', near, '/', n, '  of those, lifted>0.1m:', near_lift)
